use std::{collections::HashMap, fs, path::{Path, PathBuf}, sync::Mutex};
use rusqlite::{params, Connection};
use serde::Serialize;

pub type MetadataResult<T> = Result<T, String>;
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)] #[serde(rename_all="camelCase")]
pub enum MetadataStatus { NotConfigured, Configured }
pub trait SecretStore { fn read(&self, key:&str)->MetadataResult<Option<String>>; fn write(&self,key:&str,value:&str)->MetadataResult<()>; }
#[derive(Default)] pub struct MemorySecretStore(pub Mutex<HashMap<String,String>>);
impl SecretStore for MemorySecretStore { fn read(&self,key:&str)->MetadataResult<Option<String>> { Ok(self.0.lock().map_err(|_|"secret store unavailable".to_string())?.get(key).cloned()) } fn write(&self,key:&str,value:&str)->MetadataResult<()> { self.0.lock().map_err(|_|"secret store unavailable".to_string())?.insert(key.into(),value.into()); Ok(()) } }
pub struct WindowsCredentialStore;
impl WindowsCredentialStore { pub const SERVICE:&'static str="com.yoshima22.baconconsole"; }
impl SecretStore for WindowsCredentialStore { fn read(&self,key:&str)->MetadataResult<Option<String>> { let entry=keyring::Entry::new(Self::SERVICE,key).map_err(|e|e.to_string())?; match entry.get_password() { Ok(value)=>Ok(Some(value)), Err(keyring::Error::NoEntry)=>Ok(None), Err(error)=>Err(error.to_string()) } } fn write(&self,key:&str,value:&str)->MetadataResult<()> { keyring::Entry::new(Self::SERVICE,key).map_err(|e|e.to_string())?.set_password(value).map_err(|e|e.to_string()) } }
pub fn metadata_status(store:&impl SecretStore)->MetadataStatus { match store.read("steamgriddb-api-key") { Ok(Some(value)) if !value.trim().is_empty()=>MetadataStatus::Configured, _=>MetadataStatus::NotConfigured } }
#[derive(Clone,Copy,Debug,PartialEq,Eq)] pub enum ArtworkKind { Cover, Background, Logo }
impl ArtworkKind { fn as_str(self)->&'static str { match self { Self::Cover=>"cover",Self::Background=>"background",Self::Logo=>"logo" } } }
#[derive(Clone,Debug,Serialize)] #[serde(rename_all="camelCase")]
pub struct ArtworkRecord { pub provider:String,pub remote_id:i64,pub kind:String,pub original_url:String,pub local_path:String,pub mime:String,pub hash:String }
impl ArtworkRecord { pub fn new(provider:impl Into<String>,remote_id:i64,kind:ArtworkKind,original_url:impl Into<String>,local_path:impl Into<String>,mime:impl Into<String>,hash:impl Into<String>)->Self { Self { provider:provider.into(),remote_id,kind:kind.as_str().into(),original_url:original_url.into(),local_path:local_path.into(),mime:mime.into(),hash:hash.into() } } }
pub struct MetadataStore { db:PathBuf }
impl MetadataStore { pub fn open(root:&Path)->MetadataResult<Self> { fs::create_dir_all(root).map_err(|e|e.to_string())?; let store=Self{db:root.join("baconconsole.sqlite3")}; let conn=store.connection()?; conn.execute_batch("CREATE TABLE IF NOT EXISTS artwork_selections(game_id INTEGER NOT NULL, provider TEXT NOT NULL, remote_id INTEGER NOT NULL, kind TEXT NOT NULL, original_url TEXT NOT NULL, local_path TEXT NOT NULL, mime TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(game_id,kind));").map_err(|e|e.to_string())?; Ok(store) } fn connection(&self)->MetadataResult<Connection>{Connection::open(&self.db).map_err(|e|e.to_string())} pub fn save_selected_artwork(&self,game_id:i64,record:&ArtworkRecord)->MetadataResult<()> { self.connection()?.execute("INSERT INTO artwork_selections(game_id,provider,remote_id,kind,original_url,local_path,mime,hash) VALUES(?1,?2,?3,?4,?5,?6,?7,?8) ON CONFLICT(game_id,kind) DO UPDATE SET provider=excluded.provider,remote_id=excluded.remote_id,original_url=excluded.original_url,local_path=excluded.local_path,mime=excluded.mime,hash=excluded.hash",params![game_id,record.provider,record.remote_id,record.kind,record.original_url,record.local_path,record.mime,record.hash]).map_err(|e|e.to_string())?; Ok(()) } pub fn selected_artwork(&self,game_id:i64,kind:ArtworkKind)->MetadataResult<Option<ArtworkRecord>> { let conn=self.connection()?; let result=conn.query_row("SELECT provider,remote_id,kind,original_url,local_path,mime,hash FROM artwork_selections WHERE game_id=?1 AND kind=?2",params![game_id,kind.as_str()],|row|Ok(ArtworkRecord{provider:row.get(0)?,remote_id:row.get(1)?,kind:row.get(2)?,original_url:row.get(3)?,local_path:row.get(4)?,mime:row.get(5)?,hash:row.get(6)?})); match result { Ok(record)=>Ok(Some(record)),Err(rusqlite::Error::QueryReturnedNoRows)=>Ok(None),Err(error)=>Err(error.to_string()) } } }
